function decode(path: string) {
  let decoded: string
  try {
    decoded = decodeURIComponent(path)
  } catch {
    return null // Invalid URL encoding
  }
  return decoded
}

function syncAll(items) {
  if (items) {
    for (const item of items) {
      try {
        sync(item)
      } catch {
        if (item.retry) {
          queue(item)
        }
      }
    }
  }
}

