async function race(resultPromise, timeoutPromise) {
  // Attach no-op handlers so the losing promise is not an unhandled rejection.
  resultPromise.catch(() => {});
  timeoutPromise.catch(() => {});
  return Promise.race([resultPromise, timeoutPromise]);
}

async function cleanup(dir) {
